@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Fredoka:wght@400;500;600;700&display=swap');
:root{--ink:#172343;--muted:#7582a0;--yellow:#ffd86b;--coral:#ff786d;--sky:#9bdcf0;--lav:#aaa3ff;--cream:#fffaf0;--navy:#101837;--panel:rgba(255,255,255,.92)}
*{box-sizing:border-box}html,body{height:100%;margin:0}body{background:#f4f4fa;color:var(--ink);font-family:'DM Sans',sans-serif;display:flex;justify-content:center;align-items:center;padding:18px}.app-shell{width:min(1240px,100%);height:min(820px,calc(100dvh - 36px));min-height:570px;display:flex;flex-direction:column;gap:12px}.topbar{height:54px;flex-shrink:0;display:flex;align-items:center;justify-content:space-between;padding:0 6px}.brand{display:flex;align-items:center;gap:9px;color:#253050;text-decoration:none;font:600 14px 'Fredoka',sans-serif;letter-spacing:1.5px}.brand b{font-weight:700;color:#796de4}.brand-mark{width:29px;height:29px;display:grid;place-items:center;border-radius:10px;background:#ffe69a;color:#a77500;font-size:19px;box-shadow:0 4px 10px #ecd58e80}.top-actions{display:flex;align-items:center;gap:9px}.quiet-button,.icon-button{height:38px;border:1px solid #e6e8f1;background:#fff;border-radius:12px;color:#455170;font:700 12px 'DM Sans';cursor:pointer;transition:.18s}.quiet-button{padding:0 11px;display:flex;align-items:center;gap:7px}.quiet-button:hover,.icon-button:hover{transform:translateY(-2px);box-shadow:0 6px 15px #27334e1c}.quiet-button>span:first-child{font-size:15px;color:#8275e8}.collection-count{padding:3px 6px;border-radius:7px;background:#f0efff;color:#7769d8;font-size:10px}.icon-button{width:39px;font-size:17px}
.game-frame{position:relative;flex:1;min-height:0;overflow:hidden;border-radius:25px;background:#91d9ee;box-shadow:0 18px 50px #202d5120,0 2px 6px #202d5110;isolation:isolate}canvas{display:block;width:100%;height:100%}.canvas-vignette{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 100px #16244b12;border-radius:inherit}.hud{position:absolute;z-index:2;top:17px;left:19px;right:19px;display:flex;align-items:flex-start;gap:24px;pointer-events:none}.hud[hidden]{display:none}.hud-pill{height:52px;padding:7px 12px;display:flex;align-items:center;gap:9px;border-radius:14px;background:#fffefaed;box-shadow:0 5px 16px #2c315325;backdrop-filter:blur(8px)}.hud-icon{font-size:21px}.hud-pill small{display:block;font-weight:800;font-size:8px;letter-spacing:1.1px;color:#8991a5}.hud-pill strong{font:600 16px 'Fredoka';color:#28314c}.hud-pill i{font-style:normal;font-size:10px;color:#8991a5}.course-progress{flex:1;padding-top:5px;max-width:510px;margin:0 auto}.progress-track{height:10px;margin-top:12px;border-radius:10px;background:#ffffffa8;border:2px solid #fff;position:relative;box-shadow:0 3px 9px #29404a20}.progress-fill{position:absolute;inset:0 auto 0 0;width:0;border-radius:8px;background:linear-gradient(90deg,#ffcc68,#ff8e73)}.progress-runner{position:absolute;left:0;top:50%;transform:translate(-50%,-55%);color:#fff;font-size:15px;text-shadow:0 1px 5px #59607a}.progress-labels{display:flex;justify-content:space-between;color:#fff;text-shadow:0 1px 4px #365b69aa;font-size:8px;letter-spacing:1px;font-weight:800;margin:6px 2px}.hud-right{display:flex;gap:8px;pointer-events:auto}.keepsake-pill{gap:7px}.keepsake-pill>span{font-size:17px;color:#e9a43c}.keepsake-pill strong{font-size:17px}.pause-button{height:48px;width:48px;border:0;background:#fffefaed;font-size:20px;box-shadow:0 5px 16px #2c315325}.page-footer{flex-shrink:0;height:24px;display:flex;justify-content:space-between;align-items:center;padding:0 8px;color:#8e95a8;font-size:10px;font-weight:700;letter-spacing:.35px}.page-footer span:first-child{color:#787f96}
.screen{position:absolute;inset:0;z-index:4;display:flex;align-items:center;justify-content:center}.screen[hidden]{display:none}.start-screen{justify-content:flex-start;background:linear-gradient(100deg,#111a39 0%,#151f43f5 43%,#151f4380 70%,transparent 100%);color:white}.intro-copy{position:relative;z-index:2;padding:35px 0 42px 7.5%;width:55%;max-width:590px}.eyebrow{font-size:9px;letter-spacing:1.8px;font-weight:800;color:#91dced}.eyebrow .sparkle{font-size:13px;color:#ffd86b;margin-right:5px}.intro-copy h1{font:600 clamp(56px,8vw,95px)/.86 'Fredoka',sans-serif;letter-spacing:-3px;margin:20px 0 17px;color:#fff}.intro-copy h1 span:first-child{color:#ffd86b}.title-period{color:#ff8177}.intro-text{color:#d2d7e8;font-size:14px;line-height:1.75;margin:0 0 17px}.intro-tags{display:flex;gap:9px;margin:0 0 24px}.intro-tags span{font-size:10px;font-weight:700;color:#d9def1;background:#ffffff12;border:1px solid #ffffff20;border-radius:20px;padding:7px 10px}.primary-button{height:49px;min-width:192px;padding:0 15px 0 20px;display:inline-flex;align-items:center;justify-content:space-between;gap:22px;border:0;border-radius:14px;background:var(--yellow);color:#3b3440;font:800 12px 'DM Sans';letter-spacing:.8px;cursor:pointer;box-shadow:0 7px 0 #d9a83b,0 12px 25px #0e142755;transition:transform .15s,box-shadow .15s}.primary-button:hover{transform:translateY(-2px);box-shadow:0 9px 0 #d9a83b,0 15px 25px #0e142755}.primary-button:active{transform:translateY(4px);box-shadow:0 3px 0 #d9a83b}.button-arrow{font-size:19px;font-weight:500;line-height:1}.controls-hint{margin-top:20px;color:#a8b1ce;font-size:9px;font-weight:700;letter-spacing:.6px}.controls-hint kbd{font:700 9px 'DM Sans';color:#fff;border:1px solid #ffffff4d;background:#ffffff19;border-radius:4px;padding:3px 5px;margin-left:2px}.screen-footer{position:absolute;bottom:15px;left:22px;right:22px;display:flex;justify-content:space-between;color:#b5bdd4;font-size:9px;font-weight:700;letter-spacing:.5px}.screen-footer span:first-child{color:#ffe59c}
.hero-art{position:absolute;width:52%;height:100%;right:0;top:0;overflow:hidden;background:linear-gradient(145deg,#86d7ed 0%,#a7e7ec 65%,#c9efda 100%);clip-path:polygon(15% 0,100% 0,100% 100%,0 100%);z-index:0}.hero-sun{position:absolute;right:14%;top:12%;width:86px;height:86px;border-radius:50%;background:#ffe490;box-shadow:0 0 0 16px #ffe49034,0 0 50px #fff3ae80}.hero-star{position:absolute;color:#fff6c9;text-shadow:0 2px 10px #ffffff90}.star-a{right:49%;top:20%;font-size:23px}.star-b{right:17%;top:42%;font-size:30px}.hero-cloud{position:absolute;width:92px;height:23px;border-radius:50px;background:#ffffffbd;filter:drop-shadow(0 5px 5px #468da524)}.hero-cloud:before,.hero-cloud:after{content:'';position:absolute;bottom:4px;border-radius:50%;background:inherit}.hero-cloud:before{width:35px;height:34px;left:16px}.hero-cloud:after{width:26px;height:26px;left:40px}.cloud-a{top:29%;left:18%;transform:scale(.8)}.cloud-b{top:17%;right:7%;transform:scale(1.05)}.hero-platform{position:absolute;bottom:16%;left:7%;width:100%;height:28%;border-radius:24px 24px 0 0;transform:skewY(-7deg);box-shadow:0 18px 0 #4c9a87}.platform-back{bottom:38%;left:36%;width:80%;height:13%;background:#d1bbff;box-shadow:0 13px 0 #8578cb;border:4px solid #fff9}.platform-front{background:linear-gradient(120deg,#81e0b5,#55c9a2);border-top:6px solid #d5ffe9}.hero-character{position:absolute;bottom:34%;left:45%;width:106px;height:139px;animation:bob 1.6s ease-in-out infinite;transform:rotate(-5deg);z-index:2}.char-shadow{position:absolute;bottom:-6px;left:10px;width:96px;height:18px;border-radius:50%;background:#285e7380;filter:blur(4px)}.char-body{position:absolute;bottom:7px;left:15px;width:76px;height:96px;border-radius:37px 37px 25px 25px;background:linear-gradient(140deg,#ff9779,#f46970);border:4px solid #fff5;box-shadow:inset -9px -5px 0 #d9506040,0 9px 12px #38587934}.char-face{position:absolute;top:35px;left:19px;width:37px;height:21px}.char-face i{position:absolute;top:0;left:5px;width:5px;height:7px;background:#26344e;border-radius:50%}.char-face i:nth-child(2){left:25px}.char-face b{position:absolute;left:12px;top:11px;width:14px;height:8px;border-bottom:3px solid #26344e;border-radius:0 0 15px 15px}.char-arm{position:absolute;top:48px;width:17px;height:38px;border-radius:14px;background:#f57d73;border:3px solid #ffd1b2}.arm-left{left:-13px;transform:rotate(28deg)}.arm-right{right:-13px;transform:rotate(-42deg)}.char-feet{position:absolute;bottom:-8px;left:7px;width:22px;height:17px;border-radius:12px;background:#ffd86b;box-shadow:37px 0 #ffd86b}.hero-cape{position:absolute;left:10px;bottom:39px;width:27px;height:55px;background:#796de4;clip-path:polygon(0 0,100% 5%,72% 100%,28% 80%);transform:rotate(9deg)}.hero-speech{position:absolute;left:44%;bottom:58%;border-radius:12px 12px 12px 2px;padding:10px 12px;color:#323750;background:#fff;font:700 9px 'Fredoka';letter-spacing:.5px;transform:rotate(-6deg);box-shadow:0 5px 12px #39607124}.hero-speech span{color:#ef8774;margin-left:4px;font-size:14px}.hero-sticker{position:absolute;right:7%;bottom:12%;width:72px;height:72px;border:2px dashed #fff;border-radius:50%;transform:rotate(11deg);display:grid;align-content:center;text-align:center;background:#ffca68;color:#624c2c;font:700 13px/1.1 'Fredoka';box-shadow:0 3px 10px #5488763d}.hero-sticker b{font-size:8px;letter-spacing:.5px}
.pause-screen,.finish-screen,.collection-screen,.memory-screen{background:#101833a6;backdrop-filter:blur(6px)}.dialog-card{width:min(410px,calc(100% - 34px));text-align:center;background:#fffdf6;border-radius:24px;padding:34px 36px 30px;box-shadow:0 25px 70px #080f265c;animation:pop .25s ease-out}.dialog-icon{font-size:22px;color:#8878e8;margin-bottom:12px}.dialog-card .eyebrow{color:#998cdc;font-size:8px}.dialog-card h2{font:600 38px/.98 'Fredoka';letter-spacing:-.7px;color:#26304d;margin:13px 0}.dialog-card h2 span{color:#8977e4}.dialog-card p{color:#818aa0;font-size:12px;line-height:1.6;margin:0 auto 22px;max-width:280px}.dialog-card .primary-button{width:100%;height:47px}.text-button{display:block;border:0;background:none;color:#8189a0;text-decoration:underline;text-underline-offset:3px;font:700 10px 'DM Sans';cursor:pointer;margin:20px auto 0}.finish-card{padding-top:27px}.finish-confetti{color:#f3be4e;font-size:24px;letter-spacing:12px;margin-bottom:8px}.finish-card h2{font-size:47px;color:#7a69de;margin:9px 0}.finish-card h2 span{color:#ff8273}.finish-card p{margin-bottom:17px}.finish-stats{display:flex;justify-content:center;gap:32px;padding:15px 0;margin:0 0 15px;border-top:1px solid #eeedf3;border-bottom:1px solid #eeedf3}.finish-stats div{display:grid;gap:2px}.finish-stats b{font:600 20px 'Fredoka';color:#3f4a69}.finish-stats small{font-size:8px;color:#9da4b4;font-weight:800;letter-spacing:.8px}.finish-note{background:#fff2c9;color:#62543a;border-radius:11px;padding:12px 9px;margin-bottom:19px;font:500 12px 'Fredoka'}.finish-note span{display:block;font:600 9px 'DM Sans';color:#ac9254;margin-top:4px}.collection-screen{padding:24px}.collection-panel{position:relative;width:min(760px,100%);max-height:100%;overflow:auto;background:#fffdf6;border-radius:24px;padding:32px 38px 23px;box-shadow:0 25px 70px #080f265c;animation:pop .25s ease-out}.close-button{position:absolute;right:20px;top:16px;border:0;background:#f0eff7;width:32px;height:32px;border-radius:10px;color:#646d87;font-size:23px;cursor:pointer}.collection-panel .eyebrow{color:#9a8bda}.collection-panel h2{font:600 35px 'Fredoka';margin:7px 0 2px;color:#283450}.collection-panel h2 span{color:#8372e4}.collection-subtitle{color:#8991a5;font-size:12px;margin:0 0 20px}.memory-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.memory-tile{position:relative;min-height:107px;text-align:left;border:1px solid #eeeaf1;border-radius:15px;padding:15px 15px 13px 50px;background:#fff;overflow:hidden}.memory-tile:before{content:'✦';position:absolute;left:14px;top:15px;display:grid;place-items:center;width:25px;height:25px;border-radius:9px;background:#fff0c8;color:#d9a43c}.memory-tile.locked{background:#f5f4f8;border-style:dashed}.memory-tile.locked:before{content:'?';background:#e8e7f1;color:#9a9bb0;font-weight:800}.memory-tile h3{margin:0 0 6px;color:#4f5873;font:600 13px 'Fredoka'}.memory-tile p{margin:0;color:#878ea2;font-size:10px;line-height:1.55}.memory-tile.locked h3{color:#a1a5b4}.collection-foot{text-align:center;color:#8f95a8;font-size:10px;margin-top:17px}.memory-screen{z-index:6}.memory-card-pop{position:relative;width:min(390px,calc(100% - 36px));padding:33px 34px 25px;text-align:center;border-radius:24px;background:#fffdf6;box-shadow:0 25px 70px #080f265c;animation:pop .3s ease-out}.memory-spark{margin:0 auto 11px;width:43px;height:43px;display:grid;place-items:center;background:#fff1c7;color:#e4ad43;border-radius:15px;font-size:24px;transform:rotate(-6deg)}.memory-card-pop .eyebrow{color:#a491dc;font-size:8px}.memory-card-title{font:600 24px 'Fredoka';color:#323b59;margin:12px 0 8px}.memory-card-pop p{color:#727d96;font-size:13px;line-height:1.75;margin:0 0 13px}.memory-signature{font:600 11px 'Fredoka';color:#a28b52}.memory-signature span{color:#ed897d;margin-left:4px}.memory-card-pop .primary-button{width:100%;margin-top:23px}.no-rush{font-size:8px;letter-spacing:1.2px;font-weight:800;color:#afb2bf;margin-top:17px}.toast{position:absolute;z-index:7;top:84px;left:50%;transform:translate(-50%,-15px);opacity:0;pointer-events:none;display:flex;align-items:center;gap:10px;padding:11px 16px;background:#fffdf5;border-radius:14px;box-shadow:0 8px 25px #27334c40;transition:.3s}.toast.show{transform:translate(-50%,0);opacity:1}.toast-icon{font-size:20px}.toast b,.toast small{display:block}.toast b{font:600 12px 'Fredoka';color:#3b4664}.toast small{margin-top:2px;font-size:9px;color:#8991a5}.mobile-controls{position:absolute;z-index:3;bottom:14px;left:15px;right:15px;display:flex;align-items:center;justify-content:space-between;pointer-events:none}.mobile-controls[hidden]{display:none}.mobile-controls button{pointer-events:auto;width:53px;height:53px;border-radius:18px;border:1px solid #ffffffa6;background:#ffffffc9;color:#384568;font:700 22px 'DM Sans';box-shadow:0 4px 12px #25334b30;touch-action:none}.mobile-controls .jump-control{width:88px;height:62px;border-radius:22px;background:#ffd86bed;color:#493e36;font:800 10px 'DM Sans';letter-spacing:.7px}.jump-control span{font-size:18px;vertical-align:-2px;margin-left:3px}
@keyframes bob{0%,100%{transform:translateY(0) rotate(-5deg)}50%{transform:translateY(-9px) rotate(0)}}@keyframes pop{from{transform:translateY(9px) scale(.97);opacity:0}to{transform:none;opacity:1}}
@media(max-width:700px){body{padding:0;background:#111a39}.app-shell{height:100dvh;min-height:0;width:100%;gap:0}.topbar{height:48px;padding:0 13px;background:#f4f4fa}.brand{font-size:12px}.brand-mark{width:25px;height:25px}.quiet-button{height:34px}.button-label{display:none}.icon-button{width:35px;height:35px}.game-frame{border-radius:0;box-shadow:none}.page-footer{height:30px;padding:0 12px;background:#f4f4fa;font-size:8px}.page-footer span:last-child{display:none}.start-screen{background:linear-gradient(180deg,#121a3c 0%,#18234a 46%,#16234a90 68%,transparent 100%);align-items:flex-start}.intro-copy{padding:32px 22px 0;width:100%;max-width:none}.intro-copy .eyebrow{font-size:7px;letter-spacing:1.25px}.intro-copy h1{font-size:62px;margin:15px 0 10px;letter-spacing:-2px}.intro-text{font-size:12px;line-height:1.55;margin-bottom:12px}.intro-text br{display:none}.intro-tags{margin-bottom:16px}.intro-tags span{font-size:9px;padding:6px 8px}.primary-button{height:45px;min-width:173px;font-size:11px}.controls-hint{font-size:8px;margin-top:14px}.hero-art{top:39%;height:61%;width:100%;clip-path:polygon(0 10%,100% 0,100% 100%,0 100%)}.hero-sun{top:12%;width:62px;height:62px;right:12%}.hero-character{bottom:33%;left:43%;transform:scale(.82);transform-origin:bottom center}.hero-speech{bottom:57%;left:48%;font-size:8px}.hero-platform{bottom:10%;height:25%}.platform-back{bottom:35%;height:12%}.hero-sticker{bottom:8%;right:8%;width:58px;height:58px;font-size:11px}.hero-sticker b{font-size:7px}.screen-footer{bottom:12px;left:14px;right:14px;font-size:8px}.screen-footer span:last-child{display:none}.hud{left:10px;right:10px;top:12px;gap:7px}.hud-pill{height:43px;padding:6px 8px;gap:5px;border-radius:12px}.hud-icon{font-size:16px}.hud-pill small{font-size:6px;letter-spacing:.7px}.hud-pill strong{font-size:14px}.course-progress{padding-top:0}.progress-track{height:8px;margin-top:10px}.progress-labels{font-size:6px;margin-top:5px}.keepsake-pill{gap:4px}.keepsake-pill>span{font-size:13px}.keepsake-pill strong{font-size:13px}.keepsake-pill small{display:none}.pause-button{height:40px;width:40px;font-size:17px}.mobile-controls{bottom:13px}.dialog-card{padding:29px 24px 24px}.dialog-card h2{font-size:33px}.collection-screen{padding:14px}.collection-panel{padding:28px 20px 18px;border-radius:20px}.collection-panel h2{font-size:30px}.memory-grid{gap:8px}.memory-tile{min-height:120px;padding:13px 10px 10px 42px}.memory-tile:before{left:9px;top:12px;width:24px;height:24px}.memory-tile h3{font-size:12px}.memory-tile p{font-size:9px}.collection-foot{font-size:9px}.memory-card-pop{padding:27px 24px 20px}.memory-card-pop p{font-size:12px}.toast{top:68px;max-width:calc(100% - 32px);width:max-content}.finish-card h2{font-size:41px}.finish-stats{gap:21px}}
@media(max-height:650px) and (min-width:701px){.intro-copy{padding-top:20px;padding-bottom:22px}.intro-copy h1{font-size:68px;margin:12px 0}.intro-text{font-size:12px}.intro-tags{margin-bottom:16px}.controls-hint{margin-top:15px}.hero-art{transform:scale(.92);transform-origin:right center}.dialog-card{padding-top:24px;padding-bottom:22px}}

(() => {
  'use strict';

  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = {
    start: $('startScreen'), pause: $('pauseScreen'), finish: $('finishScreen'), collection: $('collectionScreen'), memory: $('memoryScreen'),
    hud: $('hud'), mobile: $('mobileControls'), progress: $('progressFill'), distance: $('distanceReadout'), runCount: $('inRunCount'), count: $('collectionCount'),
    memoryGrid: $('memoryGrid'), title: $('memoryTitle'), message: $('memoryMessage'), eyebrow: $('memoryEyebrow'), toast: $('toast'), toastTitle: $('toastTitle'), toastBody: $('toastBody')
  };

  const COURSE_LENGTH = 4200;
  const memories = [
    { id: 'laugh', x: 510, icon: '☺', title: 'That one-of-a-kind laugh', message: 'I remember that laugh of yours so clearly. The kind that made me start laughing too, even when I had no idea what was so funny. I still carry it with me.' },
    { id: 'wrestle', x: 1450, icon: '✊', title: 'The wrestling champion', message: 'I remember when we used to wrestle and tumble around together. You were little, but somehow you had the strength of about twelve tiny bears. Those moments mean the world to me.' },
    { id: 'fortnite', x: 2580, icon: '🎮', title: 'Battle Royale legend', message: 'You were one of the greatest five-year-olds I ever saw play Fortnite. Your strategy was elite. Your victory dances were… legally unstoppable.' },
    { id: 'love', x: 3650, icon: '💛', title: 'A note that never changes', message: 'I love you. I always want to be with you, and I will never leave you. Being apart was not my choice. You are always in my heart, wherever you are.' }
  ];
  const obstacles = [
    { x: 760, w: 70, h: 65, type: 'crate', label: 'BONK BOX' },
    { x: 1040, w: 130, h: 25, type: 'bar', label: 'DUCK!' },
    { x: 1320, w: 90, h: 76, type: 'crate', label: 'BONK BOX' },
    { x: 1830, w: 58, h: 99, type: 'spinner', label: 'WHOOSH' },
    { x: 2110, w: 95, h: 67, type: 'crate', label: 'BONK BOX' },
    { x: 2390, w: 135, h: 24, type: 'bar', label: 'DUCK!' },
    { x: 2860, w: 65, h: 90, type: 'spinner', label: 'WHOOSH' },
    { x: 3140, w: 120, h: 66, type: 'crate', label: 'BONK BOX' },
    { x: 3470, w: 70, h: 75, type: 'crate', label: 'BONK BOX' },
    { x: 3910, w: 125, h: 25, type: 'bar', label: 'DUCK!' }
  ];
  const gaps = [{x:900,w:95},{x:1580,w:115},{x:2260,w:90},{x:3000,w:105},{x:3730,w:100}];
  const checkpoints = [0, 1200, 2400, 3500];
  const achievements = [
    { id:'first-jump', title:'Gravity? Never heard of her.', body:'You made your first jump!', check:g=>g.jumps>0 },
    { id:'first-memory', title:'Pocket-sized nostalgia', body:'You found your first keepsake.', check:g=>g.collected.size>0 },
    { id:'all-memory', title:'A full heart (and pockets)', body:'You found every keepsake.', check:g=>g.collected.size===memories.length },
    { id:'finish', title:'Legend status: confirmed', body:'You conquered the whole course!', check:g=>g.finished }
  ];
  let W=0,H=0,dpr=1,last=0,raf=0,toastTimer=0,soundOn=false,audio;
  let state='start', keys={left:false,right:false}, game=null;

  function resize(){
    const r=canvas.getBoundingClientRect(); dpr=Math.min(window.devicePixelRatio||1,2);
    W=r.width; H=r.height; canvas.width=Math.max(1,Math.round(W*dpr)); canvas.height=Math.max(1,Math.round(H*dpr));
    ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  window.addEventListener('resize',resize,{passive:true}); resize();
  function groundY(){ return H * (W<650 ? .76 : .78); }
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
